const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const agudo = ee.Geometry.Point([-53.2492, -29.6465]); // Agudo, Brazil coordinates
  const roi = agudo.buffer(5000); // 5 km radius

  const date1_start = '2023-11-04';
  const date1_end = '2023-11-06'; // +/- 1 day around Nov 5
  const date2_start = '2023-11-20';
  const date2_end = '2023-11-22'; // +/- 1 day around Nov 21

  const scale = 30; // Sentinel-2 resolution is 10m, but 30m for faster processing is acceptable for area calculation

  // Function to mask clouds in Sentinel-2 images
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000)
      .select(['B3', 'B8']) // Select Green and NIR bands for NDWI
      .copyProperties(image, ['system:time_start']);
  }

  // Function to calculate NDWI and create water mask
  function calculateWaterMask(image) {
    // NDWI = (Green - NIR) / (Green + NIR) for Sentinel-2: (B3 - B8) / (B3 + B8)
    const ndwi = image.normalizedDifference(['B3', 'B8']).rename('NDWI');
    // Threshold NDWI to classify water. A common threshold is > 0.
    const waterMask = ndwi.gt(0.1).rename('water_mask'); // Using 0.1 for a slightly stricter water detection
    return waterMask.updateMask(waterMask); // Mask non-water pixels
  }

  // Function to process and get water area for a given date range
  async function getWaterArea(startDate, endDate, periodName) {
    let collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
      .filterBounds(roi)
      .filterDate(startDate, endDate)
      .map(maskS2clouds)
      .map(calculateWaterMask);

    const initialSize = await collection.size().getInfo();
    if (initialSize === 0) {
      console.log(`${periodName} Images: 0. Trying wider date range.`);
      // Widen the date range if no images found
      const widerStartDate = ee.Date(startDate).advance(-3, 'day').format('YYYY-MM-dd').getInfo();
      const widerEndDate = ee.Date(endDate).advance(3, 'day').format('YYYY-MM-dd').getInfo();
      console.log(`Wider range: ${widerStartDate} to ${widerEndDate}`);

      collection = ee.ImageCollection('COPERNICUS/S2_SR_HARMONIZED')
        .filterBounds(roi)
        .filterDate(widerStartDate, widerEndDate)
        .map(maskS2clouds)
        .map(calculateWaterMask);

      const widerSize = await collection.size().getInfo();
      if (widerSize === 0) {
        console.log(`No images found for ${periodName} even with wider range.`);
        return { area: null, count: 0, image_count: 0 };
      }
      console.log(`${periodName} Images (Wider): ${widerSize}`);
    } else {
      console.log(`${periodName} Images: ${initialSize}`);
    }

    // Take the median of valid water masks for the period
    const waterMaskImage = collection.median().clip(roi);

    // Calculate valid pixel count for the water mask (i.e., water pixels)
    const waterPixels = await waterMaskImage.reduceRegion({
      reducer: ee.Reducer.sum(), // sum of 1s (water pixels)
      geometry: roi,
      scale: scale,
      maxPixels: 1e9
    }).get('water_mask').getInfo();

    if (waterPixels === null || waterPixels === undefined) {
      console.log(`Calculation failure for ${periodName}.`);
      return { area: null, count: 0, image_count: initialSize };
    }

    const waterAreaSqM = waterPixels * (scale * scale);
    const waterAreaSqKm = waterAreaSqM / 1e6;

    console.log(`${periodName} Water Pixels: ${waterPixels} (Area: ${waterAreaSqKm.toFixed(2)} km²)`);
    return { area: waterAreaSqKm, count: waterPixels, image_count: initialSize };
  }

  // Get water area for both periods
  let result1 = await getWaterArea(date1_start, date1_end, "Period 1 (Nov 5)");
  let result2 = await getWaterArea(date2_start, date2_end, "Period 2 (Nov 21)");

  // 5. Validation & Final Answer
  if (result1.image_count === 0 || result2.image_count === 0) {
    console.log("C1: Empty Collection (No images found in date/location for one or both comparison points).");
    return;
  }

  if (result1.area === null || result2.area === null) {
    console.log("C3: Calculation Failure (Result is None, NaN, or invalid).");
    return;
  }

  // If both have valid pixel counts, but zero water pixels, that's a valid zero area.
  // C2 is for when no *base image* pixels exist after masking, not when *water pixels* are zero.
  // Since we check image_count for C1 and result.area for C3, we can assume valid data here.

  if (result2.area > result1.area) {
    console.log("A: Yes");
  } else {
    console.log("B: No");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
